      "hwy.membership.dialog.localApprove.meetingReportLabel": "\u062A\u0642\u0631\u064A\u0631 \u0627\u0644\u0644\u0642\u0627\u0621 \u0645\u0639 \u0627\u0644\u0645\u0646\u062A\u0638\u0645 \u0648\u0634\u0631\u062D \u0639\u0646\u0647",
