      "hwy.membership.dialog.localApprove.tosighPanelInstruction": "\u0643\u0648\u062F \u0627\u0644\u062A\u0648\u062B\u064A\u0642 \u0647\u0648 \u0631\u0645\u0632 \u0645\u0646 4 \u0623\u0631\u0642\u0627\u0645 \u0642\u062F \u062A\u0645 \u0625\u0631\u0633\u0627\u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u0645\u0646\u062A\u0638\u0645 \u0639\u0628\u0631 \u0631\u0633\u0627\u0644\u0629 \u0646\u0635\u064A\u0629. \u0639\u0646\u062F \u0627\u0644\u062A\u0648\u0627\u0635\u0644 \u0645\u0639 \u0627\u0644\u0645\u0646\u062A\u0638\u0645 \u0644\u063A\u0631\u0636 \u0627\u0644\u062A\u0648\u062B\u064A\u0642\u060C \u064A\u062C\u0628 \u0623\u0646 \u062A\u0623\u062E\u0630 \u0645\u0646\u0647 \xAB\u0643\u0648\u062F \u0627\u0644\u062A\u0648\u062B\u064A\u0642\xBB \u0648\u062A\u0643\u062A\u0628\u0647 \u0647\u0646\u0627 \u0648\u0630\u0644\u0643 \u0644\u0644\u062A\u0623\u0643\u062F \u0628\u0623\u0646\u0643 \u0642\u062F \u062A\u0648\u0627\u0635\u0644\u062A \u0645\u0639 \u0627\u0644\u0645\u0646\u062A\u0638\u0645 \u0628\u0627\u0644\u0641\u0639\u0644!",
      "hwy.membership.dialog.localApprove.tosighPanelTitle": "\u0643\u0648\u062F \u0627\u0644\u062A\u0648\u062B\u064A\u0642",
      "hwy.membership.dialog.localApprove.warningBody": "\u0639\u0645\u0644\u064A\u0629 \u0627\u0644\u062A\u0648\u062B\u064A\u0642 \u0627\u0644\u0645\u062D\u0644\u064A \u062A\u064F\u0633\u062C\u0651\u064E\u0644 \u0628\u0627\u0633\u0645\u0643 \u0641\u064A \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A. \u064A\u062C\u0628 \u0623\u0646 \u062A\u0648\u062B\u0651\u0642 \u0641\u0642\u0637 \u0645\u0646 \u062A\u0639\u0631\u0641\u0647\u0645 \u0634\u062E\u0635\u064A\u0627\u064B. \u0627\u0630\u0643\u0631 \u0643\u064A\u0641 \u062A\u0639\u0631\u0641 \u0627\u0644\u0634\u062E\u0635 \u0648\u0639\u0644\u0627\u0642\u062A\u0643 \u0628\u0647\u060C \u0648\u0645\u0627 \u062F\u0627\u0631 \u0641\u064A \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u2014 \u062A\u062C\u0646\u0651\u0628 \u0627\u0644\u0639\u0628\u0627\u0631\u0627\u062A \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u0627\u0644\u0645\u0643\u0631\u0631\u0629.",
      "hwy.membership.dialog.localApprove.warningLead": "\u0644\u0627 \u062A\u0642\u0645 \u0628\u062A\u0648\u062B\u064A\u0642 \u0634\u062E\u0635 \u0644\u0627 \u062A\u0639\u0631\u0641\u0647!",
      "hwy.membership.dialog.localApprove.warningTitle": "\u062A\u062D\u0630\u064A\u0631\u0627\u064B \u062A\u062D\u0630\u064A\u0631\u0627\u064B!",
      "hwy.membership.dialog.localReject.notePlaceholder": "\u0627\u0634\u0631\u062D \u0647\u0646\u0627 \u0633\u0628\u0628 \u0631\u0641\u0636 \u0627\u0644\u0627\u0633\u062A\u0645\u0627\u0631\u0629",
      "hwy.membership.dialog.localReject.warningBody": "\u0644\u0627 \u062A\u0631\u0641\u0636 \u0623\u064A \u0633\u062C\u0644 \u0628\u0633\u0647\u0648\u0644\u0629. \u062D\u0627\u0648\u0644 \u0623\u0646 \u062A\u062A\u0648\u0627\u0635\u0644 \u0645\u0639 \u0627\u0644\u0645\u0646\u062A\u0638\u0645. \u062D\u0627\u0648\u0644 \u0623\u0646 \u062A\u062C\u062F\u0647 \u0641\u064A \u0645\u0646\u0637\u0642\u0629 \u0633\u0643\u0646\u0647. \u0644\u0627 \u062A\u0642\u0645 \u0628\u0627\u0644\u0631\u0641\u0636 \u0628\u0633\u0647\u0648\u0644\u0629. \u0644\u0627 \u062A\u0642\u0645 \u0628\u0627\u0644\u0631\u0641\u0636 \u0625\u0644\u0627 \u0623\u0646 \u0639\u062C\u0632\u062A \u0639\u0646 \u0625\u0646\u062C\u0627\u0632 \u0627\u0644\u0623\u0645\u0631!",
      "hwy.membership.dialog.localReject.warningTitle": "\u062A\u062D\u0630\u064A\u0631\u060C \u062A\u062D\u0630\u064A\u0631!",
      "hwy.membership.dialog.noteLabel": "\u0627\u0644\u062A\u0648\u0636\u064A\u062D",
