      "hwy.targhinMembers.column.decision": "\u0627\u0644\u0642\u0631\u0627\u0631",
      "hwy.targhinMembers.column.processNotes": "\u0645\u0633\u0627\u0631 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0629",
