      "install.cache.dbIndex": "\u0634\u0627\u062E\u0635 DB",
      "install.cache.dbIndexAria": "\u0634\u0627\u062E\u0635 Redis DB",
      "install.cache.intro": "\u062D\u0627\u0641\u0638\u0647 \u067E\u0646\u0647\u0627\u0646 \u0627\u0634\u062A\u0631\u0627\u06A9\u06CC \u0627\u062E\u062A\u06CC\u0627\u0631\u06CC \u0628\u0631\u0627\u06CC \u0686\u0646\u062F\u06CC\u0646 \u06AF\u0631\u0647. \u06AF\u0631\u0647 \u0647\u0627 \u0647\u0645\u0627\u0647\u0646\u06AF \u0646\u06CC\u0633\u062A\u0646\u062F - \u0641\u0642\u0637 PostgreSQL \u0648 Redis \u0628\u0647 \u0627\u0634\u062A\u0631\u0627\u06A9 \u06AF\u0630\u0627\u0634\u062A\u0647 \u0645\u06CC \u0634\u0648\u0646\u062F.",
      "install.cache.memory.line1": "\u062F\u0627\u062F\u0647\u200C\u0647\u0627\u06CC \u06A9\u0634 \u0631\u0627 \u062F\u0631 \u0627\u06CC\u0646 \u0641\u0631\u0622\u06CC\u0646\u062F AppEndO \u0646\u06AF\u0647 \u0645\u06CC\u200C\u062F\u0627\u0631\u062F - \u0628\u062F\u0648\u0646 \u0633\u0631\u0648\u06CC\u0633 \u0627\u0636\u0627\u0641\u06CC \u0628\u0631\u0627\u06CC \u0646\u0635\u0628.",
      "install.cache.memory.line2": "\u0633\u0631\u06CC\u0639\u200C\u062A\u0631\u06CC\u0646 \u0631\u0627\u0647\u200C\u0627\u0646\u062F\u0627\u0632\u06CC \u0628\u0631\u0627\u06CC \u0646\u0648\u062F \u06A9\u0627\u0645\u0644\u060C \u062A\u0648\u0633\u0639\u0647 \u0645\u062D\u0644\u06CC \u0648 \u0628\u0627\u0631\u0647\u0627\u06CC \u06A9\u0627\u0631\u06CC \u0633\u0628\u06A9.",
      "install.cache.memory.line3": "\u0647\u0646\u06AF\u0627\u0645 \u0631\u0627\u0647 \u0627\u0646\u062F\u0627\u0632\u06CC \u0645\u062C\u062F\u062F \u06AF\u0631\u0647\u060C \u062D\u0627\u0641\u0638\u0647 \u067E\u0646\u0647\u0627\u0646 \u0627\u0632 \u0628\u06CC\u0646 \u0645\u06CC \u0631\u0648\u062F. \u06AF\u0631\u0647 \u0647\u0627\u06CC \u062F\u06CC\u06AF\u0631 \u0646\u0645\u06CC \u062A\u0648\u0627\u0646\u0646\u062F \u0627\u06CC\u0646 \u062D\u0627\u0641\u0638\u0647 \u0631\u0627 \u0628\u0647 \u0627\u0634\u062A\u0631\u0627\u06A9 \u0628\u06AF\u0630\u0627\u0631\u0646\u062F.",
      "install.cache.memory.title": "\u062D\u0627\u0641\u0638\u0647",
