      "operations.recordEvents.retention.dryRunInfo": "\u0641\u0642\u0637 \u067E\u06CC\u0634\u200C\u0646\u0645\u0627\u06CC\u0634. \u0631\u062F\u06CC\u0641\u200C\u0647\u0627\u06CC \u0631\u0648\u06CC\u062F\u0627\u062F \u0631\u06A9\u0648\u0631\u062F \u0648 \u062F\u0641\u062A\u0631 \u067E\u06CC\u0627\u0645 \u0631\u0627 \u06A9\u0647 \u062E\u0637\u200C\u0645\u0634\u06CC \u0630\u062E\u06CC\u0631\u0647\u200C\u0634\u062F\u0647 \u062F\u0631 \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u2192 \u06AF\u0632\u0627\u0631\u0634\u200C\u0647\u0627 \u0627\u0632 \u067E\u0627\u06CC\u06AF\u0627\u0647 \u0639\u0645\u0644\u06CC\u0627\u062A\u06CC \u06A9\u067E\u06CC \u0648 \u0633\u067E\u0633 \u062D\u0630\u0641 \u0645\u06CC\u200C\u06A9\u0646\u062F \u0634\u0645\u0627\u0631\u0634 \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0628\u0631\u0627\u06CC \u0631\u0648\u06CC\u062F\u0627\u062F\u0647\u0627 \u0633\u0648\u0627\u0628\u0642 \u0646\u06AF\u0647\u062F\u0627\u0631\u06CC\u200C\u0634\u062F\u0647 \u0648 \u0646\u06AF\u0647\u062F\u0627\u0631\u06CC \u0642\u0627\u0646\u0648\u0646\u06CC \u0631\u062F \u0645\u06CC\u200C\u0634\u0648\u0646\u062F. \u0686\u06CC\u0632\u06CC \u06A9\u067E\u06CC\u060C \u062D\u0630\u0641 \u06CC\u0627 \u062F\u0631 \u0635\u0641 \u0642\u0631\u0627\u0631 \u0646\u0645\u06CC\u200C\u06AF\u06CC\u0631\u062F.",
      "operations.recordEvents.retention.runNowInfo": "\u06A9\u0627\u0631 \u0646\u06AF\u0647\u062F\u0627\u0631\u06CC \u062F\u0627\u0645\u0646\u0647 \u0631\u0648\u06CC\u062F\u0627\u062F\u0647\u0627\u06CC \u0631\u06A9\u0648\u0631\u062F \u0631\u0627 \u0628\u0627 \u062E\u0637\u200C\u0645\u0634\u06CC \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u0630\u062E\u06CC\u0631\u0647\u200C\u0634\u062F\u0647 \u062F\u0631 \u0635\u0641 \u0642\u0631\u0627\u0631 \u0645\u06CC\u200C\u062F\u0647\u062F. \u0631\u0648\u06CC\u062F\u0627\u062F\u0647\u0627 \u0648 \u062F\u0641\u062A\u0631 \u067E\u06CC\u0627\u0645\u200C\u0647\u0627\u06CC \u0645\u0646\u0637\u0628\u0642 \u0628\u0647 \u0645\u0642\u0635\u062F \u06A9\u067E\u06CC \u0648 \u0627\u0632 \u0627\u06CC\u0646 \u067E\u0627\u06CC\u06AF\u0627\u0647 \u062D\u0630\u0641 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F\u061B \u0628\u0631\u0627\u06CC \u0631\u0648\u06CC\u062F\u0627\u062F\u0647\u0627 \u062E\u0631\u062F Archived \u0631\u0648\u06CC \u062E\u0637 \u0632\u0645\u0627\u0646\u06CC \u0645\u06CC\u200C\u0645\u0627\u0646\u062F. \u0633\u0648\u0627\u0628\u0642 \u0646\u06AF\u0647\u062F\u0627\u0631\u06CC\u200C\u0634\u062F\u0647 \u0645\u06CC\u200C\u0645\u0627\u0646\u0646\u062F. \u067E\u06CC\u0634\u0631\u0641\u062A \u0631\u0627 \u062F\u0631 \u0635\u0641\u062D\u0647 \u06A9\u0627\u0631\u0647\u0627 \u0628\u0628\u06CC\u0646\u06CC\u062F.",
