      "rdpHub.guacdUnreachable.linux.debian": "\u06AF\u0632\u06CC\u0646\u0647 B - \u0628\u0633\u062A\u0647 \u0627\u0648\u0628\u0648\u0646\u062A\u0648 / \u062F\u0628\u06CC\u0627\u0646 (\u0628\u062F\u0648\u0646 \u062F\u0627\u06A9\u0631):",
      "rdpHub.guacdUnreachable.linux.docker": "\u06AF\u0632\u06CC\u0646\u0647 A - Docker (\u0647\u0631 \u062A\u0648\u0632\u06CC\u0639). \u06CC\u06A9 \u0628\u0627\u0631 \u0638\u0631\u0641 \u0631\u0627 \u0627\u06CC\u062C\u0627\u062F \u06A9\u0646\u06CC\u062F. \u0628\u0648\u062A \u0647\u0627\u06CC \u0628\u0639\u062F\u06CC \u0622\u0646 \u0631\u0627 \u0628\u0647 \u062F\u0644\u06CC\u0644 \u0631\u0627\u0647 \u0627\u0646\u062F\u0627\u0632\u06CC \u0645\u062C\u062F\u062F \u0627\u062F\u0627\u0645\u0647 \u0645\u06CC \u062F\u0647\u0646\u062F \u0645\u06AF\u0631 \u0627\u06CC\u0646\u06A9\u0647 \u0645\u062A\u0648\u0642\u0641 \u0634\u0648\u062F:",
      "rdpHub.guacdUnreachable.linux.dockerStart": "\u0627\u06AF\u0631 \u0638\u0631\u0641 \u0627\u0632 \u0642\u0628\u0644 \u0648\u062C\u0648\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F:",
      "rdpHub.guacdUnreachable.linux.env": "\u0627\u06AF\u0631 \u0646\u0642\u0637\u0647 \u067E\u0627\u06CC\u0627\u0646\u06CC \u0645\u0648\u0631\u062F \u0628\u0631\u0631\u0633\u06CC 127.0.0.1:4822 \u0646\u06CC\u0633\u062A\u060C GUACD_HOST \u0648 GUACD_PORT \u0631\u0627 \u062F\u0631 AppEndO .env \u062A\u0646\u0638\u06CC\u0645 \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0645\u0637\u0627\u0628\u0642\u062A \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u0646\u062F\u060C \u0633\u067E\u0633 AppEndO \u0631\u0627 \u0645\u062C\u062F\u062F\u0627 \u0631\u0627\u0647 \u0627\u0646\u062F\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F.",
      "rdpHub.guacdUnreachable.linux.intro": "\u0647\u0646\u06AF\u0627\u0645\u06CC \u06A9\u0647 AppEndO \u0631\u0648\u06CC \u0644\u06CC\u0646\u0648\u06A9\u0633 \u0646\u0635\u0628 \u0645\u06CC \u0634\u0648\u062F\u060C \u0627\u06CC\u0646 \u0628\u062E\u0634 \u0631\u0627 \u062F\u0646\u0628\u0627\u0644 \u06A9\u0646\u06CC\u062F. guacd \u0631\u0627 \u0641\u0642\u0637 \u0631\u0648\u06CC \u0627\u06CC\u0646 \u0645\u06CC\u0632\u0628\u0627\u0646 AppEndO \u0646\u0635\u0628 \u06A9\u0646\u06CC\u062F.",
      "rdpHub.guacdUnreachable.linux.other": "Fedora\u060C RHEL\u060C SUSE \u0648 \u0633\u0627\u06CC\u0631 \u062A\u0648\u0632\u06CC\u0639\u200C\u0647\u0627: Docker \u0631\u0627 \u062A\u0631\u062C\u06CC\u062D \u062F\u0647\u06CC\u062F. \u0627\u06AF\u0631 \u0628\u0633\u062A\u0647 \u062A\u0648\u0632\u06CC\u0639\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F \u0645\u0639\u0645\u0648\u0644\u0627\u064B guacd \u06CC\u0627 guacamole-server \u0646\u0627\u0645\u06CC\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F - \u0622\u0646 \u0633\u0631\u0648\u06CC\u0633 \u0631\u0627 \u0641\u0639\u0627\u0644 \u0648 \u0631\u0627\u0647\u200C\u0627\u0646\u062F\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0633\u067E\u0633 \u067E\u0648\u0631\u062A 4822 \u0631\u0627 \u0645\u0637\u0627\u0628\u0642 \u0628\u0627\u0644\u0627 \u062A\u0623\u06CC\u06CC\u062F \u06A9\u0646\u06CC\u062F.",
      "rdpHub.guacdUnreachable.linux.title": "\u0647\u0627\u0633\u062A \u0644\u06CC\u0646\u0648\u06A9\u0633",
      "rdpHub.guacdUnreachable.linux.verify": "\u062A\u0623\u06CC\u06CC\u062F \u06A9\u0646\u06CC\u062F \u06A9\u0647 guacd \u062F\u0631 \u067E\u0648\u0631\u062A \u06A9\u0627\u0648\u0634 \u0634\u062F\u0647 \u06AF\u0648\u0634 \u0645\u06CC \u062F\u0647\u062F:",
      "rdpHub.guacdUnreachable.refresh": "\u067E\u0633 \u0627\u0632 \u06AF\u0648\u0634 \u062F\u0627\u062F\u0646 guacd\u060C \u0627\u06CC\u0646 \u0635\u0641\u062D\u0647 \u0631\u0627 \u0628\u0627\u0632\u062E\u0648\u0627\u0646\u06CC \u06A9\u0646\u06CC\u062F. \u0647\u0646\u06AF\u0627\u0645\u06CC \u06A9\u0647 AppEndO \u0628\u062A\u0648\u0627\u0646\u062F \u0628\u0647 \u0646\u0642\u0637\u0647 \u067E\u0627\u06CC\u0627\u0646\u06CC \u0628\u0631\u0633\u062F\u060C \u0647\u0634\u062F\u0627\u0631 \u067E\u0627\u06A9 \u0645\u06CC \u0634\u0648\u062F.",
      "rdpHub.guacdUnreachable.windows.commandRun": "docker run -d --name guacd -- \u0631\u0627\u0647 \u0627\u0646\u062F\u0627\u0632\u06CC \u0645\u062C\u062F\u062F \u0645\u06AF\u0631 \u0627\u06CC\u0646\u06A9\u0647 \u0645\u062A\u0648\u0642\u0641 \u0634\u0648\u062F -p 4822:4822 guacamole/guacd",
      "rdpHub.guacdUnreachable.windows.commandStart": "\u0627\u062C\u0631\u0627\u06CC:\ndocker start guacd",
      "rdpHub.guacdUnreachable.windows.commandVerify": "\u0628\u0631\u0631\u0633\u06CC:\ndocker ps --filter name=guacd\nTest-NetConnection 127.0.0.1 -Port 4822",
      "rdpHub.guacdUnreachable.windows.commandWsl": "\u0628\u0647 \u0631\u0648\u0632 \u0631\u0633\u0627\u0646\u06CC sudo apt\nsudo apt install -y guacd\n\u0633\u0631\u0648\u06CC\u0633 sudo guacd start",
      "rdpHub.guacdUnreachable.windows.env": "\u0627\u06AF\u0631 \u0646\u0642\u0637\u0647 \u067E\u0627\u06CC\u0627\u0646\u06CC \u0645\u0648\u0631\u062F \u0628\u0631\u0631\u0633\u06CC 127.0.0.1:4822 \u0646\u06CC\u0633\u062A\u060C GUACD_HOST \u0648 GUACD_PORT \u0631\u0627 \u062F\u0631 AppEndO .env \u0631\u0648\u06CC \u0622\u062F\u0631\u0633\u06CC \u062A\u0646\u0638\u06CC\u0645 \u06A9\u0646\u06CC\u062F \u06A9\u0647 Docker \u06CC\u0627 WSL \u0648\u0627\u0642\u0639\u0627\u064B \u0628\u0647 \u0622\u0646 \u06AF\u0648\u0634 \u0645\u06CC \u062F\u0647\u062F\u060C \u0633\u067E\u0633 AppEndO \u0631\u0627 \u062F\u0648\u0628\u0627\u0631\u0647 \u0631\u0627\u0647 \u0627\u0646\u062F\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F.",
      "rdpHub.guacdUnreachable.windows.intro": "\u0647\u0646\u06AF\u0627\u0645\u06CC \u06A9\u0647 AppEndO \u0628\u0631 \u0631\u0648\u06CC \u0648\u06CC\u0646\u062F\u0648\u0632 \u0646\u0635\u0628 \u0645\u06CC \u0634\u0648\u062F\u060C \u0627\u06CC\u0646 \u0628\u062E\u0634 \u0631\u0627 \u062F\u0646\u0628\u0627\u0644 \u06A9\u0646\u06CC\u062F. \u0622\u067E\u0627\u0686\u06CC \u0646\u0635\u0628 \u06A9\u0646\u0646\u062F\u0647 Guacd \u0648\u06CC\u0646\u062F\u0648\u0632 \u0628\u0648\u0645\u06CC \u0631\u0627 \u0627\u0631\u0633\u0627\u0644 \u0646\u0645\u06CC \u06A9\u0646\u062F \u2014 guacd \u0631\u0627 \u062F\u0631 Docker \u062F\u0631 \u0627\u06CC\u0646 \u0645\u06CC\u0632\u0628\u0627\u0646 AppEndO \u0627\u062C\u0631\u0627 \u06A9\u0646\u06CC\u062F.",
      "rdpHub.guacdUnreachable.windows.step1": "1. Docker Desktop \u0631\u0627 \u0628\u0631\u0627\u06CC \u0648\u06CC\u0646\u062F\u0648\u0632 \u0646\u0635\u0628 \u06A9\u0631\u062F\u0647 \u0648 \u0622\u0646 \u0631\u0627 \u0631\u0627\u0647 \u0627\u0646\u062F\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F. \u067E\u0634\u062A\u06CC\u0628\u0627\u0646 WSL 2 \u0631\u0627 \u062F\u0631 \u062D\u06CC\u0646 \u0631\u0627\u0647 \u0627\u0646\u062F\u0627\u0632\u06CC \u0641\u0639\u0627\u0644 \u06A9\u0646\u06CC\u062F\u060C \u0633\u067E\u0633 \u0645\u0646\u062A\u0638\u0631 \u0628\u0645\u0627\u0646\u06CC\u062F \u062A\u0627 Docker \u06AF\u0632\u0627\u0631\u0634 \u062F\u0647\u062F \u06A9\u0647 \u062F\u0631 \u062D\u0627\u0644 \u0627\u062C\u0631\u0627 \u0627\u0633\u062A.",
      "rdpHub.guacdUnreachable.windows.step2": "2. PowerShell \u0631\u0627 \u0628\u0627\u0632 \u06A9\u0646\u06CC\u062F \u0648 \u06CC\u06A9 \u0628\u0627\u0631 \u06A9\u0627\u0646\u062A\u06CC\u0646\u0631 \u0631\u0627 \u0627\u06CC\u062C\u0627\u062F \u06A9\u0646\u06CC\u062F. \u0627\u06CC\u0646 guacd \u0631\u0627 \u062F\u0631 TCP 4822 \u062F\u0631 \u0627\u06CC\u0646 \u062F\u0633\u062A\u06AF\u0627\u0647 \u0645\u0646\u062A\u0634\u0631 \u0645\u06CC \u06A9\u0646\u062F:",
      "rdpHub.guacdUnreachable.windows.step3": "3. \u0627\u06AF\u0631 \u0622\u0646 \u0638\u0631\u0641 \u0627\u0632 \u0642\u0628\u0644 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F\u060C \u0628\u0647 \u062C\u0627\u06CC \u0627\u06CC\u062C\u0627\u062F \u062F\u0648\u0628\u0627\u0631\u0647 \u0622\u0646\u060C \u0622\u0646 \u0631\u0627 \u0631\u0627\u0647 \u0627\u0646\u062F\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F:",
      "rdpHub.guacdUnreachable.windows.step4": "4. \u062A\u0623\u06CC\u06CC\u062F \u06A9\u0646\u06CC\u062F \u06A9\u0647 \u06A9\u0627\u0646\u062A\u06CC\u0646\u0631 \u0628\u0627\u0644\u0627 \u0627\u0633\u062A \u0648 \u067E\u0648\u0631\u062A 4822 \u0627\u062A\u0635\u0627\u0644\u0627\u062A \u0631\u0627 \u0645\u06CC \u067E\u0630\u06CC\u0631\u062F:",
