      "install.cache.intro": "\u0630\u0627\u0643\u0631\u0629 \u062A\u062E\u0632\u064A\u0646 \u0645\u0624\u0642\u062A \u0645\u0634\u062A\u0631\u0643\u0629 \u0627\u062E\u062A\u064A\u0627\u0631\u064A\u0629 \u0644\u0639\u0642\u062F \u0645\u062A\u0639\u062F\u062F\u0629. \u0627\u0644\u0639\u0642\u062F \u0644\u0627 \u062A\u0646\u0633\u0642\u060C \u062A\u062A\u0645 \u0645\u0634\u0627\u0631\u0643\u0629 PostgreSQL \u0648Redis \u0641\u0642\u0637.",
      "install.cache.memory.line1": "\u064A\u062D\u062A\u0641\u0638 \u0628\u0628\u064A\u0627\u0646\u0627\u062A \u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0645\u0624\u0642\u062A \u062F\u0627\u062E\u0644 \u0639\u0645\u0644\u064A\u0629 AppEndO \u0647\u0630\u0647 - \u0648\u0644\u0627 \u062A\u0648\u062C\u062F \u062E\u062F\u0645\u0629 \u0625\u0636\u0627\u0641\u064A\u0629 \u0644\u0644\u062A\u062B\u0628\u064A\u062A.",
      "install.cache.memory.line2": "\u0627\u0644\u0623\u0633\u0631\u0639 \u0641\u064A \u0627\u0644\u0625\u0639\u062F\u0627\u062F \u0644\u0644\u0639\u0642\u062F\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0648\u0627\u0644\u062A\u0637\u0648\u064A\u0631 \u0627\u0644\u0645\u062D\u0644\u064A \u0648\u0623\u062D\u0645\u0627\u0644 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062E\u0641\u064A\u0641\u0629.",
      "install.cache.memory.line3": "\u064A\u062A\u0645 \u0641\u0642\u062F\u0627\u0646 \u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0645\u0624\u0642\u062A \u0639\u0646\u062F \u0625\u0639\u0627\u062F\u0629 \u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0639\u0642\u062F\u0629\u061B \u0644\u0627 \u064A\u0645\u0643\u0646 \u0644\u0644\u0639\u0642\u062F \u0627\u0644\u0623\u062E\u0631\u0649 \u0645\u0634\u0627\u0631\u0643\u0629 \u0647\u0630\u0647 \u0627\u0644\u0630\u0627\u0643\u0631\u0629.",
