      "rdpHub.guacdUnreachable.windows.commandWsl": "\u0633\u0648\u062F\u0648 \u0627\u0644\u062A\u062D\u062F\u064A\u062B \u0627\u0644\u0645\u0646\u0627\u0633\u0628\nsudo apt install -y guacd\n\u0628\u062F\u0621 \u062E\u062F\u0645\u0629 Sudo guacd",
      "rdpHub.guacdUnreachable.windows.env": "\u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0646\u0642\u0637\u0629 \u0627\u0644\u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0645 \u0641\u062D\u0635\u0647\u0627 \u0644\u064A\u0633\u062A 127.0.0.1:4822\u060C \u0641\u0642\u0645 \u0628\u062A\u0639\u064A\u064A\u0646 GUACD_HOST \u0648GUACD_PORT \u0641\u064A AppEndO .env \u0639\u0644\u0649 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0630\u064A \u064A\u0633\u062A\u0645\u0639 \u0625\u0644\u064A\u0647 Docker \u0623\u0648 WSL \u0628\u0627\u0644\u0641\u0639\u0644\u060C \u062B\u0645 \u0623\u0639\u062F \u062A\u0634\u063A\u064A\u0644 AppEndO.",
      "rdpHub.guacdUnreachable.windows.intro": "\u0627\u062A\u0628\u0639 \u0647\u0630\u0627 \u0627\u0644\u0642\u0633\u0645 \u0639\u0646\u062F \u062A\u062B\u0628\u064A\u062A AppEndO \u0639\u0644\u0649 \u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 Windows. \u0644\u0627 \u064A\u0642\u0648\u0645 Apache \u0628\u0634\u062D\u0646 \u0645\u062B\u0628\u062A Windows guacd \u0627\u0644\u0623\u0635\u0644\u064A \u2014 \u0642\u0645 \u0628\u062A\u0634\u063A\u064A\u0644 guacd \u0641\u064A Docker \u0639\u0644\u0649 \u0645\u0636\u064A\u0641 AppEndO \u0647\u0630\u0627.",
      "rdpHub.guacdUnreachable.windows.step1": "1. \u0642\u0645 \u0628\u062A\u062B\u0628\u064A\u062A Docker Desktop \u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 Windows \u0648\u0627\u0628\u062F\u0623 \u062A\u0634\u063A\u064A\u0644\u0647. \u0642\u0645 \u0628\u062A\u0645\u0643\u064A\u0646 \u0627\u0644\u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u062E\u0644\u0641\u064A\u0629 \u0644\u0640 WSL 2 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u060C \u062B\u0645 \u0627\u0646\u062A\u0638\u0631 \u062D\u062A\u0649 \u064A\u0628\u0644\u063A Docker \u0639\u0646 \u062A\u0634\u063A\u064A\u0644\u0647.",
      "rdpHub.guacdUnreachable.windows.step2": "2. \u0627\u0641\u062A\u062D PowerShell \u0648\u0642\u0645 \u0628\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062D\u0627\u0648\u064A\u0629 \u0645\u0631\u0629 \u0648\u0627\u062D\u062F\u0629. \u064A\u0646\u0634\u0631 \u0647\u0630\u0627 guacd \u0639\u0644\u0649 TCP 4822 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062C\u0647\u0627\u0632:",
      "rdpHub.guacdUnreachable.windows.step3": "3. \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0647\u0630\u0647 \u0627\u0644\u062D\u0627\u0648\u064A\u0629 \u0645\u0648\u062C\u0648\u062F\u0629 \u0628\u0627\u0644\u0641\u0639\u0644\u060C \u0641\u0627\u0628\u062F\u0623 \u062A\u0634\u063A\u064A\u0644\u0647\u0627 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u0625\u0646\u0634\u0627\u0626\u0647\u0627 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649:",
      "rdpHub.guacdUnreachable.windows.step4": "4. \u062A\u0623\u0643\u062F \u0645\u0646 \u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u062D\u0627\u0648\u064A\u0629 \u0648\u0623\u0646 \u0627\u0644\u0645\u0646\u0641\u0630 4822 \u064A\u0642\u0628\u0644 \u0627\u0644\u0627\u062A\u0635\u0627\u0644\u0627\u062A:",
      "rdpHub.guacdUnreachable.windows.title": "\u0645\u0636\u064A\u0641 \u0648\u064A\u0646\u062F\u0648\u0632",
      "rdpHub.guacdUnreachable.windows.wsl": "\u0625\u0630\u0627 \u0644\u0645 \u062A\u062A\u0645\u0643\u0646 \u0645\u0646 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 Docker Desktop\u060C \u0641\u0642\u0645 \u0628\u062A\u062B\u0628\u064A\u062A guacd \u062F\u0627\u062E\u0644 WSL (Ubuntu) \u0639\u0644\u0649 \u0646\u0641\u0633 \u062C\u0647\u0627\u0632 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u0648\u0627\u0633\u062A\u0645\u0631 \u0641\u064A \u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u062E\u062F\u0645\u0629 \u062D\u062A\u0649 \u064A\u062A\u0645\u0643\u0646 Windows \u0645\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 127.0.0.1:4822:",
